mapper.select:
SELECT id,user_id,request_id,app_id,api_id,auth_decision,auth_reason,operation_type,target_type,target_id,
    source_system,external_event_id,status,evidence,created_at
FROM sys_operation_log
WHERE target_type='USER' AND target_id IS NOT NULL
  AND operation_type IN ('USER_ROLE_GRANT','USER_ROLE_REVOKE','HR_POSITION_REVOKE','HR_GRANTS_REVOKE_ALL','OA_DECISION')
AND target_id=#{user}
AND id<#{before}
ORDER BY id DESC LIMIT #{limit}
